<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/doctor_online_v580.php';header('Content-Type: application/json; charset=utf-8');$out=function(array $d,int $code=200){http_response_code($code);echo json_encode($d,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;};try{$me=current_user();if(!$me)$out(['ok'=>false,'error'=>'Login required'],401);$cid=(int)($_REQUEST['consultation_id']??0);$q=db()->prepare('SELECT c.*,a.id appointment_id,a.doctor_id,a.organization_id,a.patient_user_id,d.user_id doctor_user_id FROM health_consultations_v580 c JOIN health_appointments_v580 a ON a.id=c.appointment_id JOIN health_doctors_v580 d ON d.id=a.doctor_id WHERE c.id=? AND c.tenant_id=? LIMIT 1');$q->execute([$cid,do580_tid()]);$c=$q->fetch();if(!$c||!do580_can_access_appointment($c,$me))$out(['ok'=>false,'error'=>'Room access denied'],403);$isDoctor=(int)$c['doctor_user_id']===(int)$me['id'];db()->prepare('UPDATE health_consultations_v580 SET '.($isDoctor?'doctor_joined_at':'patient_joined_at').'=COALESCE('.($isDoctor?'doctor_joined_at':'patient_joined_at').',NOW()),status=IF(status=\'ended\',status,\'active\'),updated_at=NOW() WHERE id=?')->execute([$cid]);$action=(string)($_GET['action']??$_POST['action']??'poll');if($_SERVER['REQUEST_METHOD']==='POST')csrf_check();if($action==='chat'){$m=trim((string)($_POST['message']??''));if($m==='')$out(['ok'=>false,'error'=>'Message is empty'],422);if(mb_strlen($m)>2000)$m=mb_substr($m,0,2000);$q=db()->prepare('SELECT created_at FROM health_chat_messages_v580 WHERE consultation_id=? AND sender_user_id=? ORDER BY id DESC LIMIT 1');$q->execute([$cid,(int)$me['id']]);$last=$q->fetchColumn();if($last&&time()-strtotime((string)$last)<1)$out(['ok'=>false,'error'=>'Please wait before sending another message'],429);db()->prepare("INSERT INTO health_chat_messages_v580(tenant_id,consultation_id,sender_user_id,message,message_type,created_at) VALUES(?,?,?,?,'text',NOW())")->execute([do580_tid(),$cid,(int)$me['id'],$m]);$out(['ok'=>true]);}if($action==='signal'){$type=(string)($_POST['signal_type']??'');if(!in_array($type,['offer','answer','ice','hangup'],true))$out(['ok'=>false,'error'=>'Invalid signal'],422);$payload=(string)($_POST['payload_json']??'{}');if(strlen($payload)>50000)$out(['ok'=>false,'error'=>'Signal too large'],413);db()->prepare('INSERT INTO health_call_signals_v580(consultation_id,sender_user_id,signal_type,payload_json,created_at) VALUES(?,?,?,?,NOW())')->execute([$cid,(int)$me['id'],$type,$payload]);if($type==='hangup')db()->prepare("UPDATE health_consultations_v580 SET status='ended',ended_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$cid]);$out(['ok'=>true]);}if($action==='poll'){$chatAfter=max(0,(int)($_GET['chat_after']??0));$signalAfter=max(0,(int)($_GET['signal_after']??0));$q=db()->prepare('SELECT m.id,m.sender_user_id,m.message,m.created_at,u.name sender_name FROM health_chat_messages_v580 m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.consultation_id=? AND m.id>? ORDER BY m.id ASC LIMIT 100');$q->execute([$cid,$chatAfter]);$messages=$q->fetchAll()?:[];$q=db()->prepare('SELECT id,sender_user_id,signal_type,payload_json,created_at FROM health_call_signals_v580 WHERE consultation_id=? AND id>? ORDER BY id ASC LIMIT 200');$q->execute([$cid,$signalAfter]);$signals=$q->fetchAll()?:[];$out(['ok'=>true,'messages'=>$messages,'signals'=>$signals,'status'=>$c['status']]);}$out(['ok'=>false,'error'=>'Unknown action'],404);}catch(Throwable $e){$out(['ok'=>false,'error'=>'Doctor Online request failed.'],500);}
